    10→const FString UWjWorldCosmeticSubsystem::LoadoutConfigSection = TEXT("CosmeticLoadout");
    11→
    12→void UWjWorldCosmeticSubsystem::Initialize(FSubsystemCollectionBase& Collection)
    13→{
    14→	Super::Initialize(Collection);
    15→
    16→	// DeveloperSettings에서 카탈로그 로드
    17→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    18→	if (Settings && !Settings->CosmeticCatalog.IsNull())
    19→	{
    20→		Catalog = Settings->CosmeticCatalog.LoadSynchronous();
    21→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 로드: %s"), Catalog ? *Catalog->GetName() : TEXT("실패"));
    22→	}
    23→	else
    24→	{
    25→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("DeveloperSettings에 CosmeticCatalog가 설정되지 않았습니다."));
    26→	}
    27→
    28→	LoadLoadoutFromLocal();
    29→
    30→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticSubsystem 초기화 완료"));
    31→}
    32→
    33→void UWjWorldCosmeticSubsystem::Deinitialize()
    34→{
    35→	StopInventoryPolling();
    36→	SaveLoadoutToLocal();
    37→
    38→#if WITH_STEAM
    39→	// 대기 중인 결과 핸들 정리
    40→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    41→	{
    42→		ISteamInventory* SteamInv = SteamInventory();
    43→		if (SteamInv)
    44→		{
    45→			SteamInv->DestroyResult(PendingResultHandle);
    46→		}
    47→		PendingResultHandle = k_SteamInventoryResultInvalid;
    48→	}
    49→#endif
    50→
    51→	Super::Deinitialize();
    52→}
    53→
    54→void UWjWorldCosmeticSubsystem::SetCatalog(UWjWorldCosmeticCatalogDataAsset* InCatalog)
    55→{
    56→	Catalog = InCatalog;
    57→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 설정: %s"), InCatalog ? *InCatalog->GetName() : TEXT("null"));
    58→}
    59→
    60→void UWjWorldCosmeticSubsystem::RequestInventoryRefresh()
    61→{
    62→	if (bInventoryRequestPending)
    63→	{
    64→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 요청이 이미 진행 중입니다."));
    65→		return;
    66→	}
    67→
    68→#if WITH_STEAM
    69→	ISteamInventory* SteamInv = SteamInventory();
    70→	if (!SteamInv)
    71→	{
    72→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam Inventory API를 사용할 수 없습니다."));
    73→		return;
    74→	}
    75→
    76→	// 기존 핸들 정리
    77→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    78→	{
    79→		SteamInv->DestroyResult(PendingResultHandle);
    80→		PendingResultHandle = k_SteamInventoryResultInvalid;
    81→	}
    82→
    83→	if (SteamInv->GetAllItems(&PendingResultHandle))
    84→	{
    85→		bInventoryRequestPending = true;
    86→		StartInventoryPolling();
    87→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 요청 성공 (ResultHandle: %d)"), PendingResultHandle);
    88→	}
    89→	else
    90→	{
    91→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 요청 실패"));
    92→	}
    93→#else
    94→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 미지원 환경 - 인벤토리 갱신 스킵"));
    95→	OnInventoryUpdated.Broadcast();
    96→#endif
    97→}
    98→
    99→bool UWjWorldCosmeticSubsystem::HasItem(FName ItemId) const
   100→{
   101→	return CachedInventory.ContainsByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   102→	{
   103→		return Inst.ItemId == ItemId && Inst.Quantity > 0;
   104→	});
   105→}
   106→
   107→void UWjWorldCosmeticSubsystem::GrantItemLocally(FName ItemId, int32 Quantity)
   108→{
   109→	if (ItemId.IsNone() || Quantity <= 0)
   110→	{
   111→		return;
   112→	}
   113→
   114→	// 기존 아이템 수량 증가 또는 새로 추가
   115→	FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   116→	{
   117→		return Inst.ItemId == ItemId;
   118→	});
   119→
   120→	if (Existing)
   121→	{
   122→		Existing->Quantity += Quantity;
   123→	}
   124→	else
   125→	{
   126→		FCosmeticItemInstance NewItem(ItemId);
   127→		NewItem.Quantity = Quantity;
   128→		CachedInventory.Add(NewItem);
   129→	}
   130→
   131→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로컬 아이템 부여: %s x%d"), *ItemId.ToString(), Quantity);
   132→	OnInventoryUpdated.Broadcast();
   133→}
   134→
   135→bool UWjWorldCosmeticSubsystem::EquipItem(ECosmeticSlot Slot, FName ItemId)
   136→{
   137→	if (Slot == ECosmeticSlot::None)
   138→	{
   139→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("None 슬롯에 장착할 수 없습니다."));
   140→		return false;
   141→	}
   142→
   143→	if (!HasItem(ItemId))
   144→	{
   145→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'을 보유하고 있지 않습니다."), *ItemId.ToString());
   146→		return false;
   147→	}
   148→
   149→	// 카탈로그 검증: 슬롯 일치 확인
   150→	if (Catalog)
   151→	{
   152→		const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
