   150→void UWjWorldPurchaseSubsystem::StartPurchasePolling()
   151→{
   152→	UWorld* World = GetWorld();
   153→	if (!World)
   154→	{
   155→		return;
   156→	}
   157→
   158→	// 1초 간격으로 구매 결과 폴링
   159→	World->GetTimerManager().SetTimer(
   160→		PurchasePollTimerHandle,
   161→		this,
   162→		&UWjWorldPurchaseSubsystem::PollPurchaseResult,
   163→		1.0f,
   164→		true
   165→	);
   166→
   167→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 결과 폴링 시작"));
   168→}
   169→
   170→void UWjWorldPurchaseSubsystem::StopPurchasePolling()
   171→{
   172→	UWorld* World = GetWorld();
   173→	if (World)
   174→	{
   175→		World->GetTimerManager().ClearTimer(PurchasePollTimerHandle);
   176→	}
   177→
   178→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("구매 결과 폴링 중지"));
   179→}
   180→
   181→void UWjWorldPurchaseSubsystem::PollPurchaseResult()
   182→{
   183→#if WITH_STEAM
   184→	if (CurrentState != EPurchaseState::Pending)
   185→	{
   186→		StopPurchasePolling();
   187→		return;
   188→	}
   189→
   190→	// 타임아웃 체크
   191→	UWorld* World = GetWorld();
   192→	if (World)
   193→	{
   194→		float ElapsedTime = World->GetTimeSeconds() - PurchaseStartTime;
   195→		if (ElapsedTime > PurchaseTimeoutSeconds)
   196→		{
   197→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("구매 타임아웃 (%.1f초 경과)"), ElapsedTime);
   198→			HandlePurchaseResult(false);
   199→			return;
   200→		}

