    91→
    92→#if WITH_STEAM
    93→	ISteamUserStats* SteamStats = ::SteamUserStats();
    94→	if (SteamStats && bLocalStatsLoaded)
    95→	{
    96→		SteamStats->SetStat(TCHAR_TO_UTF8(*StatName.ToString()), NewValue);
    97→	}
    98→#endif
    99→
   100→	LocalStats.FindOrAdd(StatName) = NewValue;
