    88→{
    89→	if (InDataComponentClass)
    90→	{
    91→		GameDataComponent = NewObject<UWjWorldGameDataComponent>(this, InDataComponentClass);
    92→		AddInstanceComponent(GameDataComponent);
    93→		GameDataComponent->RegisterComponent();
    94→		GameDataComponent->SetIsReplicated(true);
