   102→void AWjWorldGameStatePlay::OnRep_GamePhase()
   103→{
   104→	switch (CurrentPhase)
   105→	{
   106→	case EGamePhase::Ready:
   107→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Ready"));
   108→		break;
   109→	case EGamePhase::Playing:
   110→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Started"));
   111→		break;
   112→	case EGamePhase::Finished:
   113→		// 결과 표시는 OnRep_GameResult에서 처리
   114→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Finished"));
   115→		break;
   116→	}
