   121→void AWjWorldGameStatePlay::OnRep_IsGameStartCountDownReady()
   122→{
   123→	if (bIsGameStartCountDownReady)
   124→	{
   125→		UWorld* World = GetWorld();
   126→		if (!World) return;
   127→
   128→		APlayerController* PC = World->GetFirstPlayerController();
   129→		if (!PC) return;
   130→
   131→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   132→		if (!HUD) return;
   133→
   134→		// 늦게 참여한 클라이언트를 위해 남은 시간 계산
   135→		float RemainingTime = StartCountDownTime;
   136→		if (CountdownStartServerTime > 0.0)
   137→		{
   138→			double CurrentServerTime = GetServerWorldTimeSeconds();
   139→			double Elapsed = CurrentServerTime - CountdownStartServerTime;
   140→			RemainingTime = FMath::Max(0.0f, StartCountDownTime - static_cast<float>(Elapsed));
   141→		}
   142→
   143→		HUD->StartGameStartCountDown(RemainingTime);
   144→
   145→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Start Countdown Ready - %f seconds (original: %f)"), RemainingTime, StartCountDownTime);
